window.GDASH_FILES = {"/SCRIPTS/GAMES/Game-GeometryDash.lua":"-- toolName = TNS|Geometry Dash|TNE\n---------------------------------------------------------------\n-- Geometry Dash for 128x64 B&W EdgeTX radios (TX12, Zorro, X7)\n-- Levels: /SCRIPTS/GAMES/GDASH/L<n>.lua (first line \"-- @Name|Difficulty\").\n-- Only what the current screen needs is in memory: GDASH/pick.lua for the\n-- picker, GDASH/phys.lua + GDASH/draw.lua + the level while playing.\n-- Best % and attempts saved in /SCRIPTS/GAMES/gdash.dat.\n--\n-- Picker: wheel or right stick left/right = level,\n--         stick up/down = normal / practice,\n--         ENTER/SA/SD = play\n-- Play:   SA or SD (read as held, for ship/wave/robot/dash orbs) or ENTER (tap only).\n--         The left stick (throttle) always works too: up past the middle = held\n--         (jump), the ship and wave follow it in proportion, UFO flaps faster the\n--         higher it is, swing flips on every up/down move. SA/SD held overrides it.\n-- Practice: wheel = place checkpoint, wheel back = remove one\n-- RTN:    back to picker, RTN in picker = quit\n---------------------------------------------------------------\n\nlocal GD = \"/SCRIPTS/GAMES/GDASH/\"\n-- player fields kept in a practice checkpoint (one short string each, to save memory)\nlocal KEYS = \"x y vy g m mi du spd pc buf gr orb pad rt da y2 vy2 g2 gr2 buf2 orb2 pad2 rt2 da2\"\nlocal NLEV = 0\nlocal best, tries = {}, {}\nlocal tile, step, music, endX, newP, nr, draw, pick, mt\nlocal state, lv, prac, P, acc, pend, lastTime, deadT, cps, msg\nlocal ip = 0  -- controls: 0 SA/SD, 1 THR stick (GDASH/phys.lua reads the stick)\n\nlocal function save()\n  local s = \"v2\\n\"  -- save version; see GDASH/pick.lua\n  for i = 1, NLEV do s = s .. (best[i] or 0) .. \" \" .. (tries[i] or 0) .. \"\\n\" end\n  s = s .. \"i\" .. (ip or 0) .. \"\\n\"\n  local ok, f = pcall(io.open, \"/SCRIPTS/GAMES/gdash.dat\", \"w\")\n  if ok and f then\n    pcall(io.write, f, s)\n    pcall(io.close, f)\n  end\nend\n\nlocal function toPick()\n  tile, step, music, draw, newP, cps = nil, nil, nil, nil, nil, {}\n  collectgarbage()\n  local c = loadScript(GD .. \"pick.lua\")\n  c = c and c()\n  if c then NLEV, pick, ip = c(best, tries) end\n  state = \"pick\"\nend\n\n-- load level i, its physics and drawing; the level table is dropped after decoding\nlocal function loadLevel(i)\n  pick = nil\n  collectgarbage()\n  local c = loadScript(GD .. \"L\" .. i .. \".lua\")\n  local rows = c and c()\n  c = nil\n  if type(rows) ~= \"table\" then rows = {} end\n  c = loadScript(GD .. \"phys.lua\")\n  c = c and c()\n  if c then tile, step, music, endX, newP, nr = c(rows) end\n  rows, c = nil, nil\n  collectgarbage()\n  c = loadScript(GD .. \"draw.lua\")\n  c = c and c()\n  if c and tile then draw = c(tile, endX, nr) end\n  c = nil\n  collectgarbage()\nend\n\nlocal function pct()\n  local v = math.floor(P.x * 100 / endX)\n  if v > 100 then v = 100 elseif v < 0 then v = 0 end\n  return v\nend\n\nlocal function startRun()\n  for k, v in pairs(newP()) do P[k] = v end\n  local s = cps[#cps]\n  if prac and s then\n    local it = string.gmatch(s, \"%S+\")\n    for k in string.gmatch(KEYS, \"%S+\") do\n      local v = it()\n      if v == \"T\" then v = true elseif v == \"F\" then v = false else v = tonumber(v) end\n      P[k] = v\n    end\n  end\n  acc, pend, mt = 0, false, 0\n  music(-1)\n  state = \"play\"\nend\n\nlocal function init()\n  lv, prac, P = 1, false, {}\n  toPick()\n  lastTime = getTime()\nend\n\n-- SA/SD read as held/released every frame; edge = released->held this frame.\n-- In the picker a position kept 0.4 s becomes the rest position (toggles work).\n-- (short names: every distinct name costs radio RAM)\nlocal swR, swH, swT = {}, {}, {}  -- per switch: rest position, held, time of last change\nlocal function readSw(n)\n  local v, t = getValue(n) or 0, getTime()\n  if swR[n] == nil then swR[n], swH[n], swT[n] = v, false, t end\n  local h = math.abs(v - swR[n]) > 400\n  local e = h and not swH[n]\n  if h ~= swH[n] then swT[n] = t end\n  swH[n] = h\n  if h and state == \"pick\" and t - swT[n] > 40 then swR[n], swH[n] = v, false end\n  return h, e\nend\n\nlocal function run(event)\n  if event == EVT_VIRTUAL_EXIT then\n    save()\n    if state == \"pick\" then return 2 end\n    toPick()\n    return 0\n  end\n  -- t = 10 ms ticks since the last frame, h = SA/SD held, j = new press (SA/SD/ENTER)\n  local n = getTime()\n  local t = n - lastTime\n  lastTime = n\n  if t > 8 then t = 8 elseif t < 0 then t = 0 end\n  local h, j = readSw(\"sa\")\n  local a, b = readSw(\"sd\")\n  h, j = h or a, j or b or event == EVT_VIRTUAL_ENTER\n  local st  -- throttle stick, unless SA/SD is held\n  if not h then st = getValue(\"thr\") or 0 end\n\n  if state == \"pick\" then\n    if not pick then\n      lcd.clear()\n      lcd.drawText(2, 20, \"GDASH/pick.lua missing\", SMLSIZE)\n      return 0\n    end\n    lv, prac, ip = pick(event, lv, prac, msg, ip)\n    if j and NLEV > 0 and not msg then\n      loadLevel(lv)\n      if draw then startRun() else msg = \"GDASH/phys/draw missing\"; toPick() end\n    end\n    return 0\n  end\n  local s = \"A\" .. (tries[lv] or 0) + 1  -- HUD text, top left\n  if prac then s = \"PRAC\" .. #cps end\n  if state == \"play\" then\n    if prac and event == EVT_VIRTUAL_NEXT and #cps < 15 then\n      local c = \"\"\n      for k in string.gmatch(KEYS, \"%S+\") do\n        local v = P[k]\n        if v == true then v = \"T\" elseif v == false then v = \"F\" else v = string.format(\"%.7g\", v) end\n        c = c .. v .. \" \"\n      end\n      cps[#cps + 1] = c\n    elseif prac and event == EVT_VIRTUAL_PREV and #cps > 0 then\n      cps[#cps] = nil\n    end\n    pend = pend or j\n    acc = acc + t\n    while acc >= 2 and state == \"play\" do\n      acc = acc - 2\n      step(P, pend, h or pend, st)\n      mt = mt + 0.02\n      pend = false\n      if P.dead or P.won then\n        tries[lv] = (tries[lv] or 0) + 1\n        a = pct()\n        if P.won then a = 100 end\n        if not prac and a > (best[lv] or 0) then best[lv] = a; save()\n        elseif P.won then save() end\n        if P.won then state = \"win\"; playTone(2600, 300, 0, PLAY_NOW)\n        else state, deadT = \"dead\", 0; playTone(250, 300, 0, PLAY_NOW) end\n      end\n    end\n    if state == \"play\" then\n      music(mt)\n      -- EdgeTX runs this at a fixed 20 Hz (50 ms), so frames alternate 2 and 3\n      -- physics steps and the level would jump 3.6 / 5.4 px (seen as doubled\n      -- edges on the slow LCD). Drawing the leftover half step keeps it steady.\n      a = P.x\n      P.x = a + acc * P.spd * 0.01\n      draw(P, nil, false, s, pct(), (tries[lv] or 0) + 1)\n      P.x = a\n      return 0\n    end\n  end\n  if state == \"dead\" then\n    deadT = deadT + t / 100\n    draw(P, deadT, false, s, pct(), tries[lv] or 0)\n    if deadT > 0.8 then startRun() end\n  else\n    draw(P, nil, true, s, pct(), tries[lv] or 0)\n    lcd.drawText(14, 16, \"LEVEL COMPLETE!\", MIDSIZE + INVERS)\n    if prac then lcd.drawText(14, 32, \"Practice run\", SMLSIZE)\n    else lcd.drawText(14, 32, \"Attempts: \" .. (tries[lv] or 0), SMLSIZE) end\n    lcd.drawText(14, 42, \"ENTER = levels\", SMLSIZE)\n    if event == EVT_VIRTUAL_ENTER then save(); toPick() end\n  end\n  return 0\nend\n\n-- the tools (tools/gdash) reach step, newP, loadLevel, music and state\n-- through debug.getupvalue(run, ...), so the game carries no test hooks\nreturn { init = init, run = run }\n","/SCRIPTS/GAMES/GDASH/phys.lua":"-- Geometry Dash physics, one fixed 20 ms step. Loaded only while playing:\n--   tile, step, music, endX, newPlayer, rows = loadScript(this)()(levelTable)\n--   step(p, press, hold, st): press = new press this step (SA/SD down-edge or ENTER),\n--                         hold = SA/SD held this step (a press counts as held),\n--                         st = throttle stick getValue(\"thr\") (nil = switch controls):\n--                         held above +10%, released below -10%; the ship and the wave\n--                         follow it in proportion, the UFO flaps every 0.56 s (middle)\n--                         to 0.2 s (top), the swing flips on every up and down move\n-- editors/geodash-editor.html has a line-by-line JavaScript copy: change both.\n-- Tile table: tools/gdash/levels.txt (header) and editors/README.md. A level has\n-- 6 to 20 rows; flying modes use the whole field. Rows stay run-length coded in\n-- memory (\"c*N\" = c repeated byte(N)-32 times), see window() below.\n-- RAM: numbers are inline and locals reuse short names (every named constant and\n-- distinct name costs heap). The editor keeps the names: GY 58 ground, DT 0.02,\n-- BUF 0.12 press buffer, GC 800 gravity, JV 180 jump, PADV 250 yellow pad, GU 520 /\n-- UV 135 ufo gravity / flap, SHU 700 / SHD 600 ship accel, FM 150 ship+swing max,\n-- GB 700 / BV 60 ball, RJV 130 / RT 0.16 robot rise, SWG 600 swing gravity.\n-- Row r (0 = ground) spans y = 50 - 8r .. 58 - 8r; ceiling CY = 58 - 8N; the dual\n-- icon mirrors y as CY + 58 - size - y.\n\nreturn function(lv)\n-- N rows, ceiling CY (world y, negative for levels taller than one screen)\nlocal N = 6\nwhile N < 20 and type(lv[N + 1]) == \"string\" do N = N + 1 end\nlocal CY = 58 - 8 * N\n-- Rows stay run-length coded in memory, so a long level costs only its file\n-- size; a window of 64 columns per row is decoded when needed. For row r:\n-- W[r] coded row, W[r+N] decoded window, W[r+2N] its first column,\n-- W[r+3N] / W[r+4N] scan cursor: byte position of a token that starts at that column.\nlocal W, n = {}, 0\nfor r = 1, N do\n  local s, c, i = lv[r], 0, 1\n  if type(s) ~= \"string\" then s = \"\" end\n  for k = 1, #s do\n    if not string.byte(s, i) then break end\n    if string.byte(s, i + 1) == 42 then c, i = c + (string.byte(s, i + 2) or 33) - 32, i + 3\n    else c, i = c + 1, i + 1 end\n  end\n  W[r], W[r + N], W[r + 2 * N], W[r + 3 * N], W[r + 4 * N], lv[r] = s, \"\", -999, 1, 0, nil\n  if c > n then n = c end\nend\nlocal endX = n * 8 + 16\n\n-- decode row r's window starting at column w\n-- (s coded row, i byte position at column c, a / b first token in the window and its column)\nlocal function window(r, w)\n  if w < 0 then w = 0 end\n  local s, d, e = W[r], r + 3 * N, r + 4 * N\n  if w < W[e] then W[d], W[e] = 1, 0 end\n  local i, c, a, b = W[d], W[e], nil, 0\n  for k = 1, #s do\n    if not string.byte(s, i) or c >= w + 64 then break end\n    local n, j = 1, i + 1\n    if string.byte(s, j) == 42 then n, j = (string.byte(s, j + 1) or 33) - 32, j + 2 end\n    if c + n <= w then W[d], W[e] = j, c + n\n    elseif not a then a, b = i, c end\n    i, c = j, c + n\n  end\n  W[r + N], W[r + 2 * N] = \"\", w\n  if a then\n    -- expand \"c*N\" runs with a plain loop: a gsub callback can't be paused\n    -- by EdgeTX (\"attempt to yield across a C-call boundary\")\n    local o, j = \"\", a\n    while j < i do\n      if string.byte(s, j + 1) == 42 then\n        o, j = o .. string.rep(string.sub(s, j, j), (string.byte(s, j + 2) or 33) - 32), j + 3\n      else\n        o, j = o .. string.sub(s, j, j), j + 1\n      end\n    end\n    W[r + N] = string.sub(o, w - b + 1, w - b + 64)\n  end\nend\n\nlocal function tile(c, r)\n  if c < 0 or r < 0 or r >= N then return 46 end\n  r = r + 1\n  local i = c - W[r + 2 * N]\n  if i < 0 or i >= 64 then window(r, c - 20); i = c - W[r + 2 * N] end\n  return string.byte(W[r + N], i + 1) or 46\nend\n-- row of a y coordinate, clamped to 0..N-1\nlocal function rowOf(y)\n  local r = math.floor((57 - y) / 8)\n  if r < 0 then r = 0 elseif r >= N then r = N - 1 end\n  return r\nend\n-- solid part of a tile: \"#\" block, \"=\" slab (top half); returns top, bottom\nlocal function solid(t, r)\n  local a = 50 - 8 * r\n  if t == 35 then return a, a + 8 end\n  if t == 61 then return a, a + 4 end\n  return nil\nend\n-- slope surface: height above the tile's bottom at x offset l (0..8), and its gradient\nlocal function slope(t, l)\n  if t == 47 then return l, 1 elseif t == 96 then return 8 - l, -1\n  elseif t == 40 then return l / 2, 0.5 elseif t == 41 then return 4 + l / 2, 0.5\n  elseif t == 91 then return 8 - l / 2, -0.5 elseif t == 93 then return 4 - l / 2, -0.5 end\n  return nil\nend\n-- boxes overlap: one at (a, b) size c x d, the other at (e, f) size g x h\nlocal function hit(a, b, c, d, e, f, g, h)\n  return a < e + g and e < a + c and b < f + h and f < b + d\nend\nlocal function size(p) if p.mi then return 5 end return 7 end\n\nlocal function newPlayer()\n  return { x = 0, y = 51, vy = 0, g = 1, m = 0, mi = false, du = false, spd = 90, pc = -1,\n    buf = 0, gr = true, orb = -1, pad = -1, rt = 0, da = false,\n    y2 = 0, vy2 = 0, g2 = -1, gr2 = false, buf2 = 0, orb2 = -1, pad2 = -1, rt2 = 0, da2 = false,\n    dead = false, won = false }\nend\n\n-- dual: the second icon's fields live in *2 and are swapped in to step it\nlocal function swap(p)\n  for a, b in string.gmatch(\"y y2 vy vy2 g g2 gr gr2 buf buf2 orb orb2 pad pad2 rt rt2 da da2\", \"(%S+) (%S+)\") do\n    p[a], p[b] = p[b], p[a]\n  end\nend\n\n-- spider: jump to the nearest surface the other way (a = its y), flip gravity\nlocal function spider(p, s)\n  local g, a = p.g, CY\n  if g < 0 then a = 58 - s end\n  for c = math.floor((p.x + 1) / 8), math.floor((p.x + s - 2) / 8) do\n    for r = 0, N - 1 do\n      local t, b = solid(tile(c, r), r)\n      if t then\n        if g > 0 and b <= p.y + 1 and b > a then a = b\n        elseif g < 0 and t >= p.y + s - 1 and t - s < a then a = t - s end\n      end\n    end\n  end\n  p.y, p.g, p.vy, p.gr = a, -g, 0, false\nend\n\n-- portals in column c (a = teleport seen, b = row of its exit)\nlocal function portals(p, c)\n  local a, b = false, nil\n  for r = 0, N - 1 do\n    local t = tile(c, r)\n    if t == 71 or t == 103 then\n      p.g = 1\n      if t == 71 then p.g = -1 end\n      p.g2 = -p.g\n    elseif t >= 48 and t <= 52 then p.spd = 50 + 20 * (t - 48)\n    elseif t == 109 or t == 110 then\n      local mi = t == 109\n      if mi ~= p.mi then\n        local d = 2\n        if not mi then d = -2 end\n        if p.g > 0 then p.y = p.y + d end\n        if p.g2 > 0 then p.y2 = p.y2 + d end\n        p.mi = mi\n      end\n    elseif t == 68 then\n      if not p.du then\n        p.du, p.y2, p.vy2, p.g2, p.gr2, p.buf2 = true, CY + 58 - size(p) - p.y, -p.vy, -p.g, p.gr, p.buf\n        p.orb2, p.pad2, p.rt2, p.da2 = -1, -1, 0, false\n      end\n    elseif t == 100 then p.du = false\n    elseif t == 84 then a = true\n    elseif t == 116 then b = r\n    elseif t > 64 then\n      local i = string.find(\"CUSBWRXZ\", string.char(t), 1, true)\n      if i then p.m, p.rt, p.da, p.rt2, p.da2 = i - 1, 0, false, 0, false end\n    end\n  end\n  if a and b then\n    p.y = 50 - 8 * b\n    if p.g > 0 then p.y = p.y + 8 - size(p) end\n    p.y2 = CY + 58 - size(p) - p.y\n  end\nend\n\n-- input, orbs and pads (before the icon moves)\nlocal function pre(p, hold)\n  local s, m, g, k = size(p), p.m, p.g, 1\n  if p.mi then k = 0.8 end\n  local b = p.buf > 0\n  if m == 1 or m == 7 then\n    if b then\n      p.buf, p.gr, b = 0, false, false\n      if m == 1 then p.vy = -135 * k * g else p.g = -g; g = -g end\n    end\n  elseif m == 0 or m == 3 or m == 5 or m == 6 then\n    if p.gr and (b or (hold and m ~= 6)) then\n      p.buf, p.gr, b = 0, false, false\n      if m == 3 then p.g = -g; g = -g; p.vy = 60 * g\n      elseif m == 6 then spider(p, s); g = p.g\n      elseif m == 5 then p.vy = -130 * k * g; p.rt = 0.16\n      else p.vy = -180 * k * g end\n    end\n  end\n  local r0, r1 = rowOf(p.y + s + 3), rowOf(p.y - 4)\n  for c = math.floor((p.x - 4) / 8), math.floor((p.x + s + 3) / 8) do\n    for r = r0, r1 do\n      local t = tile(c, r)\n      if t > 96 then\n        local i, a = c * 8 + r, string.char(t)\n        local o, d = string.find(\"oirqebah\", a, 1, true), string.find(\"pkfuw\", a, 1, true)\n        if m == 4 then  -- the wave ignores jump orbs and jump pads\n          if o == 1 or o == 2 or o == 3 or o == 6 then o = nil end\n          if d and d < 4 then d = nil end\n        end\n        if o and b and i ~= p.orb and hit(p.x - 4, p.y - 4, s + 8, s + 8, c * 8, 50 - 8 * r, 8, 8) then\n          p.orb, p.buf, p.gr, p.rt, b = i, 0, false, 0, false\n          if o == 4 or o == 5 or o == 8 then p.g = -g; g = -g end\n          if o >= 7 then p.da = true; p.vy = 0\n          elseif o == 4 then p.vy = 60 * g\n          else\n            local v = 180\n            if o == 2 then v = 140 elseif o == 3 then v = 230 elseif o == 6 then v = -300 end\n            p.vy = -v * k * g\n          end\n        elseif d and i ~= p.pad and hit(p.x, p.y, s, s, c * 8, 50 - 8 * r, 8, 8) then\n          p.pad, p.gr, p.rt = i, false, 0\n          if d == 5 then spider(p, s); g = p.g\n          elseif d == 4 then p.g = -g; g = -g; p.vy = 120 * g\n          else\n            local v = 250\n            if d == 2 then v = 180 elseif d == 3 then v = 300 end\n            p.vy = -v * k * g\n          end\n        end\n      end\n    end\n  end\nend\n\n-- speed, movement, landing, death (after x has moved)\n-- (q = was on the ground, y = y before the move)\nlocal function post(p, hold, st)\n  local s, m, g, k, q = size(p), p.m, p.g, 1, p.gr\n  if p.mi then k = 0.8 end\n  if p.da and not hold then p.da = false end\n  if p.da then p.vy = 0\n  elseif m == 4 then\n    local w = p.spd\n    if p.mi then w = w * 2 end\n    if st then p.vy = -w * g * st\n    elseif hold then p.vy = -w * g else p.vy = w * g end\n  elseif st and m == 2 then\n    -- stick ship: steer the climb rate to stick * 150, at most 600 px/s2 (mini 750)\n    local d, a = -150 * st * g - p.vy, 12\n    if p.mi then a = 15 end\n    if d > a then d = a elseif d < -a then d = -a end\n    p.vy = p.vy + d\n  elseif m == 2 or m == 7 then\n    local a = 600\n    if m == 2 and hold then a = -700 end\n    if p.mi then a = a * 1.25 end\n    p.vy = p.vy + a * g * 0.02\n    if p.vy > 150 then p.vy = 150 elseif p.vy < -150 then p.vy = -150 end\n  elseif m == 5 and p.rt > 0 and hold then\n    p.vy = -130 * k * g; p.rt = p.rt - 0.02\n  else\n    p.rt = 0\n    local a = 800\n    if m == 1 then a = 520 elseif m == 3 then a = 700 end\n    p.vy = p.vy + a * g * 0.02\n  end\n  if p.vy > 350 then p.vy = 350 elseif p.vy < -350 then p.vy = -350 end\n  local y = p.y\n  p.y = p.y + p.vy * 0.02\n  p.gr = false\n  -- land on / bump into solid tiles (a = top, b = bottom; a slope's e: only its flat bottom counts)\n  local r0, r1 = rowOf(p.y + s - 1), rowOf(p.y - 1)\n  for c = math.floor((p.x + 1) / 8), math.floor((p.x + s - 2) / 8) do\n    for r = r0, r1 do\n      local t = tile(c, r)\n      local a, b = solid(t, r)\n      local e = slope(t, 0)\n      if e then a, b = 50 - 8 * r, 58 - 8 * r end\n      if a and p.y < b and p.y + s > a then\n        if p.vy * g >= 0 then\n          if g > 0 and not e and y + s <= a + 3 then p.y = a - s; p.vy = 0; p.gr = true\n          elseif g < 0 and y >= b - 3 then p.y = b; p.vy = 0; p.gr = true end\n        else\n          if g > 0 and y >= b - 3 then p.y = b; p.vy = 0\n          elseif g < 0 and not e and y + s <= a + 3 then p.y = a - s; p.vy = 0 end\n        end\n      end\n    end\n  end\n  -- slopes (normal gravity): stand on the highest point of the diagonal under the\n  -- feet, stick to it going down, leave an up slope into the air with its rise speed\n  -- (not onto a block or another slope), crash into a high side.\n  -- f feet, u / v x range, e surface y, d its gradient, n the tile after it\n  if g > 0 then\n    local f, u, v, e, d, n = p.y + s, p.x + 1, p.x + s - 1, nil, 0, 46\n    for c = math.floor(u / 8), math.floor(v / 8) do\n      for r = rowOf(f + 3), rowOf(f - 9) do\n        local t = tile(c, r)\n        local h, i = slope(t, 0)\n        if h and p.y < 58 - 8 * r then\n          local l = u - c * 8\n          if i > 0 then l = v - c * 8 end\n          if l < 0 then l = 0 elseif l > 8 then l = 8 end\n          h = slope(t, l)\n          h = 58 - 8 * r - h\n          if not e or h < e then e, d, n = h, i, tile(c + 1, r) end\n        end\n      end\n    end\n    if e and (p.vy >= 0 or p.vy >= -p.spd * d) then  -- not when rising faster than the slope (a jump)\n      local i = 0\n      if q and p.vy >= 0 then i = 3 end\n      if f >= e - i and y + s <= e + 3 + p.spd * 0.02 then\n        if d > 0 and (n == 35 or n == 61 or slope(n, 0)) then d = 0 end\n        p.y, p.vy, p.gr = e - s, -p.spd * d, true\n      elseif f > e + 3 then p.dead = true; return end\n    end\n  end\n  if p.y + s >= 58 then\n    p.y = 58 - s; p.vy = 0\n    if g > 0 then p.gr = true end\n  elseif p.y <= CY then\n    p.y = CY; p.vy = 0\n    if g < 0 then p.gr = true end\n  end\n  -- crash into block sides and spikes (d = top of the cell)\n  r0, r1 = rowOf(p.y + s - 1), rowOf(p.y)\n  for c = math.floor(p.x / 8), math.floor((p.x + s - 1) / 8) do\n    for r = r0, r1 do\n      local t = tile(c, r)\n      local a, b = solid(t, r)\n      local d = 50 - 8 * r\n      if (a and hit(p.x, p.y + 1, s, s - 2, c * 8, a, 8, b - a))\n        or (t == 94 and hit(p.x + 1, p.y + 1, s - 2, s - 2, c * 8 + 2, d + 3, 4, 5))\n        or (t == 118 and hit(p.x + 1, p.y + 1, s - 2, s - 2, c * 8 + 2, d, 4, 5)) then\n        p.dead = true\n        return\n      end\n    end\n  end\nend\n\nlocal function step(p, press, hold, st)\n  if st then\n    st = st / 1000\n    if st > 1 then st = 1 elseif st < -1 then st = -1 end\n    local a, f = p.sh or false, 0.6 - 0.4 * st\n    if st > 0.1 then p.sh = true elseif st < -0.1 then p.sh = false end\n    hold = p.sh\n    press = press or (hold ~= a and (hold or p.m == 7))\n    if p.m == 1 and hold and not press then\n      p.ft = (p.ft or 0) - 0.02\n      press = p.ft <= 0\n    end\n    if press then p.ft = f end\n  end\n  hold = hold or press\n  if press then p.buf = 0.12; p.buf2 = 0.12\n  else\n    if p.buf > 0 then p.buf = p.buf - 0.02 end\n    if p.buf2 > 0 then p.buf2 = p.buf2 - 0.02 end\n  end\n  local c = math.floor((p.x + 3) / 8)\n  if c ~= p.pc then p.pc = c; portals(p, c) end\n  pre(p, hold)\n  if p.du then swap(p); pre(p, hold); swap(p) end\n  p.x = p.x + p.spd * 0.02\n  post(p, hold, st)\n  if p.du and not p.dead then swap(p); post(p, hold, st); swap(p) end\n  if p.x >= endX and not p.dead then p.won = true end\nend\n\n-- level tune: GDASH/music.lua (a separate file, so this one compiles in less RAM);\n-- tools that load this file without loadScript get a silent tune\nlocal c = loadScript and loadScript(\"/SCRIPTS/GAMES/GDASH/music.lua\")\nlocal music = c and c()(lv.m, lv.u) or function() end\nc = nil\n\nreturn tile, step, music, endX, newPlayer, N\nend\n","/SCRIPTS/GAMES/GDASH/draw.lua":"-- Geometry Dash drawing, loaded with phys.lua only while playing:\n--   draw = loadScript(this)()(tile, endX, rows)\n--   draw(P, deadT or nil, still, hudLeft, pct, attempt)\n-- Shapes are strings of 8 lines \"x1y1x2y2\" (digits): tiles on their 8x8 cell,\n-- icons on a 7x7 grid (scaled for mini, flipped upside down with gravity).\n-- Levels taller than 6 rows scroll: world y + oy = screen y.\n-- numbers inline to save RAM: ground line y 58, icon at screen x 28\n-- tile shapes in the order of TS: orbs, pads, teleport exit, spikes, slopes\nlocal TS = \"oirqebahpkfuwt^v/`()[]\"\nlocal SH = \"11616166661616113333333333333333\" .. \"22525255552525222522252225222522\"\n  .. \"11616166661616113343344434443444\" .. \"22522353245425552555255525552555\"\n  .. \"11616166661616112255255225522552\" .. \"11611262136314641565166616661666\"\n  .. \"11616166661616112353425344534453\" .. \"11616166661616112353425344532224\"\n  .. \"16661767176717671767176717671767\" .. \"27572757275727572757275727572757\"\n  .. \"15651666176717671767176717671767\" .. \"15651767151765676567656765676567\"\n  .. \"17672537554755475547554755475547\" .. \"10176067334333433343334333433343\"\n  .. \"07313167175717571757175717571757\" .. \"00363660105010501050105010501050\"\n  .. \"07707077077707700770077007700770\" .. \"00770007077700770077007700770077\"\n  .. \"07747477077707740774077407740774\" .. \"03700307707707770370037003700370\"\n  .. \"00730007737707770073007300730073\" .. \"04770407077704770477047704770477\"\n-- icons, two animation frames per mode: cube ufo ship ball wave robot spider swing\nlocal IC = \"00606066660606002242234324442444\" .. \"30636336360303302343323432343234\"\n  .. \"03636366660606032040202340434043\" .. \"03636366660606032040202340434043\"\n  .. \"06660206026510201121112111211121\" .. \"06660206026510201121112111211121\"\n  .. \"20404063634646262603032011551155\" .. \"20404063634646262603032015511551\"\n  .. \"03606036360336033603360336033603\" .. \"03606036360336033603360336033603\"\n  .. \"10505053531313103141241644564456\" .. \"10505053531313103141242644464446\"\n  .. \"10501151125212062326434652665266\" .. \"10501151125212062326434652665266\"\n  .. \"00600666303234362242234324442444\" .. \"00600666303234362242234324442444\"\n  .. \"00663036066003636666000030366006\"   -- explosion (drawn scaled)\n\nreturn function(tile, endX, N)\nlocal TX, TY = {}, {}  -- wave trails: world points, 1-8 main icon, 9-16 dual icon\nN = N or 6\nlocal cam, oy, lx = 0, 0, 0\n\n-- (k = 1, tiles and normal-size icons, skips the scaling: same pixels, far fewer instructions)\n-- (shapes pad their 8 lines by repeating the last one: a repeat is skipped, it would draw the same pixels)\nlocal function shape(S, i, x, y, k, fl)\n  x, y = x - 48, y - 48\n  local e, f, g, h\n  for j = i, i + 28, 4 do\n    local a, b, c, d = string.byte(S, j, j + 3)\n    if a == e and b == f and c == g and d == h then return end\n    e, f, g, h = a, b, c, d\n    if k ~= 1 then\n      a, b = math.floor((a - 48) * k + 0.5) + 48, math.floor((b - 48) * k + 0.5) + 48\n      c, d = math.floor((c - 48) * k + 0.5) + 48, math.floor((d - 48) * k + 0.5) + 48\n    end\n    if fl then b, d = fl + 96 - b, fl + 96 - d end\n    lcd.drawLine(x + a, y + b, x + c, y + d, SOLID, FORCE)\n  end\nend\n\n-- one icon (o = 0 main, 8 dual); the wave leaves a short zig-zag trail\nlocal function icon(P, y, g, vy, gr, still, o)\n  local m, s, f = P.m, 7, 0\n  if P.mi then s = 5 end\n  local fl = nil\n  if g < 0 then fl = s - 1 end\n  y = math.floor(y)\n  if m == 4 then\n    for i = o + 8, o + 2, -1 do TX[i], TY[i] = TX[i - 1], TY[i - 1] end\n    TX[o + 1], TY[o + 1] = P.x, y + math.floor(s / 2)\n    for i = o + 1, o + 7 do\n      if TX[i + 1] and TX[i + 1] - cam >= 0 then\n        lcd.drawLine(math.floor(TX[i] - cam), TY[i] + oy, math.floor(TX[i + 1] - cam), TY[i + 1] + oy, SOLID, FORCE)\n      end\n    end\n    fl = nil\n    if vy > 0 then fl = s - 1 end\n  else\n    for i = o + 1, o + 8 do TX[i] = nil end\n    if (m == 0 and not still and not gr) or m == 3 or m == 5 then f = math.floor(P.x / 12) % 2 end\n  end\n  shape(IC, (m * 2 + f) * 32 + 1, 28, y + oy, (s - 1) / 6, fl)\nend\n\nreturn function(P, deadT, still, left, pct, att)\n  lcd.clear()\n  cam = math.floor(P.x) - 28\n  -- vertical camera: keep the icon between screen y 18 and 42, eased, snapped on restart\n  local t = oy\n  if P.y + t < 18 then t = 18 - P.y elseif P.y + t > 42 then t = 42 - P.y end\n  if t > 8 * N - 48 then t = 8 * N - 48 end\n  if t < 0 then t = 0 end\n  if P.x < lx or P.y + oy < 10 or P.y + oy > 52 then oy = t\n  else oy = oy + (t - oy) / 3 end\n  oy = math.floor(oy + 0.5)\n  lx = P.x\n  local m, gy, cy = P.m, 58 + oy, 58 - 8 * N + oy\n  if gy < LCD_H then\n    lcd.drawLine(0, gy, LCD_W - 1, gy, SOLID, FORCE)\n    local off = cam % 16\n    for i = 0, 8 do\n      local sx = i * 16 - off\n      if sx >= 0 and sx + 3 < LCD_W then lcd.drawLine(sx, gy + 1, sx + 3, LCD_H - 1, SOLID, FORCE) end\n    end\n  end\n  -- flying modes show the ceiling as a solid line, like the real game's bounds\n  if cy > 9 then\n    local pat = DOTTED\n    if m == 1 or m == 2 or m == 4 or m == 7 then pat = SOLID end\n    lcd.drawLine(0, cy - 1, LCD_W - 1, cy - 1, pat, FORCE)\n  end\n  local y0, y1 = cy, gy\n  if y0 < 9 then y0 = 9 end\n  if y1 > LCD_H then y1 = LCD_H end\n  -- only the rows on screen (cell top from 2 to LCD_H - 1): ra .. rb\n  local c0, ra, rb = math.floor(cam / 8), math.floor((gy - LCD_H - 8) / 8) + 1, math.floor((gy - 10) / 8)\n  if ra < 0 then ra = 0 end\n  if rb > N - 1 then rb = N - 1 end\n  for c = c0, c0 + 16 do\n    local sx = c * 8 - cam\n    for r = ra, rb do\n      local top = gy - 8 * r - 8\n      local t = tile(c, r)\n      if t == 35 or t == 61 then\n        local h, x0, x1 = 8, sx, sx + 8\n        if t == 61 then h = 4 end\n        if top + h > LCD_H then h = LCD_H - top end\n        if x0 < 0 then x0 = 0 end\n        if x1 > LCD_W then x1 = LCD_W end\n        if x1 - x0 > 1 then lcd.drawRectangle(x0, top, x1 - x0, h) end\n        if t == 35 and sx >= 0 and sx <= LCD_W - 8 then lcd.drawPoint(sx + 3, top + 3) end\n      elseif t ~= 46 and sx >= 0 and sx <= LCD_W - 8 then\n        local ch = string.char(t)\n        local i = string.find(TS, ch, 1, true)\n        if i then shape(SH, i * 32 - 31, sx, top, 1, nil)\n        elseif string.find(\"CUSBWRXZGg01234mnDdT\", ch, 1, true) then\n          if y1 - y0 > 1 then lcd.drawRectangle(sx + 1, y0, 5, y1 - y0) end\n          lcd.drawText(sx + 1, top + 1, ch, SMLSIZE)\n        end\n      end\n    end\n  end\n  local sx = endX - cam\n  if sx >= 0 and sx < LCD_W then lcd.drawLine(sx, y0, sx, y1 - 1, DOTTED, FORCE) end\n  sx = 40 - cam\n  if sx > 0 and sx < LCD_W - 60 then lcd.drawText(sx, 24, \"Attempt \" .. att, SMLSIZE) end\n  if deadT then\n    local d = math.floor(deadT * 40) + 2\n    if d > 13 then d = 13 end\n    shape(IC, 513, 31 - d, math.floor(P.y) + oy + 3 - d, d / 3, nil)\n    if P.du then shape(IC, 513, 31 - d, math.floor(P.y2) + oy + 3 - d, d / 3, nil) end\n  else\n    icon(P, P.y, P.g, P.vy, P.gr, still, 0)\n    if P.du then icon(P, P.y2, P.g2, P.vy2, P.gr2, still, 8) end\n  end\n  -- scrolled tiles may reach into the HUD strip\n  if N > 6 then lcd.drawFilledRectangle(0, 0, LCD_W, 9, ERASE) end\n  lcd.drawText(1, 1, left, SMLSIZE)\n  lcd.drawRectangle(32, 2, 62, 5)\n  local w = math.floor(pct * 60 / 100)\n  if w > 0 then lcd.drawFilledRectangle(33, 3, w, 3, FORCE) end\n  lcd.drawText(LCD_W - 1, 1, pct .. \"%\", SMLSIZE + RIGHT)\nend\nend\n","/SCRIPTS/GAMES/GDASH/music.lua":"-- Geometry Dash level tune player, loaded by phys.lua (kept out of it so each file\n-- compiles on the radio in less RAM):  music = loadScript(this)()(lv.m, lv.u)\n-- music(t) with t = seconds since the attempt started queues each note when its\n-- time comes, t < 0 restarts; the tune loops.\n-- Token: note letter, optional #, octave digit, length digit (units of u s); R<n> = rest.\n-- editors/geodash-editor.html has a JavaScript copy (tok / makeMusic): change both.\nreturn function(mel, u)\n-- i = byte position of the next token, e = its start time\nlocal i, e = 1, 0\nu = tonumber(u) or 0.1\nif type(mel) ~= \"string\" then mel = nil end\n-- token at byte position j: next position, frequency (0 = rest), length\nlocal function tok(j)\n  local a, b, w = string.find(mel, \"(%S+)\", j)\n  if not a then return nil end\n  if string.sub(w, 1, 1) == \"R\" then return b + 1, 0, tonumber(string.sub(w, 2, 2)) or 1 end\n  local c, o, d = string.match(w, \"^(%u#?)(%d)(%d)$\")\n  if not c then return b + 1, 0, 1 end\n  if string.len(c) == 1 then c = c .. \" \" end\n  a = string.find(\"C C#D D#E F F#G G#A A#B \", c, 1, true) or 19\n  a = 12 * (tonumber(o) + 1) + (a - 1) / 2  -- MIDI note\n  return b + 1, 440 * 2 ^ ((a - 69) / 12), tonumber(d) or 1\nend\nlocal function music(t)\n  if not mel then return end\n  if t < 0 then i, e = 1, 0; return end\n  for k = 1, 4 do\n    if e > t then break end\n    local j, f, n = tok(i)\n    if not j then j, f, n = tok(1) end\n    if not j then mel = nil; return end\n    n = n * u\n    if f > 0 and t - e < 0.1 then playTone(math.floor(f), math.floor(n * 1000) - 20, 0, 0) end\n    i, e = j, e + n\n  end\nend\n\nreturn music\nend\n","/SCRIPTS/GAMES/GDASH/pick.lua":"-- Geometry Dash level picker, loaded only while the picker is shown (dropped while playing).\n--   nlev, pick = loadScript(this)()(best, tries)  counts the levels, reads gdash.dat into best/tries\n--   lv, prac, ip = pick(event, lv, prac, msg, ip) draws one frame (ip: 0 SA/SD, 1 THR stick)\nlocal stx, sty, str, hl, nm, df, tr, ip = 0, 0, 0, -1, \"\", \"\", \"\", 0\n\nreturn function(best, tries)\n-- levels are counted on the card: L1, L2, ... until one is missing (max 99)\nlocal n = 0\nfor i = 1, 99 do\n  local ok, f = pcall(io.open, \"/SCRIPTS/GAMES/GDASH/L\" .. i .. \".lua\", \"r\")\n  if not ok or not f then break end\n  pcall(io.close, f)\n  n, best[i], tries[i] = i, 0, 0\nend\nlocal ok, f = pcall(io.open, \"/SCRIPTS/GAMES/gdash.dat\", \"r\")\nif ok and f then\n  local ok2, s = pcall(io.read, f, 1200)\n  pcall(io.close, f)\n  if ok2 and type(s) == \"string\" then\n    -- \"v2\" first line = saved since the long levels came in; an older file's\n    -- L1-L8 results belong to the old short levels, so they start again from 0\n    local i, o = 0, string.sub(s, 1, 3) ~= \"v2\\n\"\n    for b, a in string.gmatch(s, \"(%d+) (%d+)\") do\n      i = i + 1\n      if i <= n and not (o and i <= 8) then best[i] = tonumber(b) or 0; tries[i] = tonumber(a) or 0 end\n    end\n    ip = tonumber(string.match(s, \"\\ni(%d)\")) or 0\n  end\nend\n\nreturn n, function(event, lv, prac, msg, ip)\n  local ax, ay, az = getValue(\"ail\"), getValue(\"ele\"), getValue(\"rud\")\n  local mv = 0\n  if event == EVT_VIRTUAL_NEXT then mv = 1 elseif event == EVT_VIRTUAL_PREV then mv = -1 end\n  if stx == 0 and ax > 600 then mv, stx = 1, 1 elseif stx == 0 and ax < -600 then mv, stx = -1, 1\n  elseif ax > -300 and ax < 300 then stx = 0 end\n  if sty == 0 and (ay > 600 or ay < -600) then prac, sty = not prac, 1\n  elseif ay > -300 and ay < 300 then sty = 0 end\n  lcd.clear()\n  lcd.drawText(1, 0, \"GEOMETRY DASH\", SMLSIZE + INVERS)\n  if n == 0 or msg then\n    lcd.drawText(2, 20, msg or \"No levels found in\", SMLSIZE)\n    if not msg then lcd.drawText(2, 30, \"/SCRIPTS/GAMES/GDASH/\", SMLSIZE) end\n    return lv, prac, ip\n  end\n  lv = lv + mv\n  if lv < 1 then lv = n elseif lv > n then lv = 1 end\n  -- name and difficulty: first line of the level file, \"-- @Name|Difficulty\"\n  -- or \"-- @Name|Difficulty|Official level it is a tribute to\"\n  if hl ~= lv then\n    hl, nm, df, tr = lv, \"Level \" .. lv, \"?\", \"\"\n    local ok, f = pcall(io.open, \"/SCRIPTS/GAMES/GDASH/L\" .. lv .. \".lua\", \"r\")\n    if ok and f then\n      local ok2, s = pcall(io.read, f, 80)\n      pcall(io.close, f)\n      local a, d, t = string.match(ok2 and type(s) == \"string\" and s or \"\", \"^%-%- @([^|%c]*)|([^|%c]*)|?([^%c]*)\")\n      if a and a ~= \"\" then nm = a end\n      if d and d ~= \"\" then df = d end\n      tr = t or \"\"\n    end\n  end\n  local b = best[lv] or 0\n  lcd.drawText(LCD_W - 1, 0, \"<\" .. lv .. \"/\" .. n .. \">\", SMLSIZE + RIGHT)\n  lcd.drawText(2, 10, nm, MIDSIZE)\n  lcd.drawText(2, 24, df, SMLSIZE)\n  if b >= 100 then lcd.drawText(LCD_W - 1, 24, \"COMPLETE\", SMLSIZE + INVERS + RIGHT) end\n  lcd.drawText(2, 33, \"Best \" .. b .. \"%\", SMLSIZE)\n  lcd.drawText(LCD_W - 1, 33, \"Tries \" .. (tries[lv] or 0), SMLSIZE + RIGHT)\n  lcd.drawRectangle(2, 42, 124, 4)\n  if b > 0 then lcd.drawFilledRectangle(3, 43, math.floor(b * 122 / 100), 2, FORCE) end\n  if prac then lcd.drawText(2, 48, \"PRACTICE (stick up/dn)\", SMLSIZE)\n  else lcd.drawText(2, 48, \"NORMAL (stick up/dn)\", SMLSIZE) end\n  -- bottom line: the start hint, taking turns with the tribute every 2 s\n  -- (long names go without \"tribute: \", the line holds about 28 characters)\n  if tr ~= \"\" and getTime() % 400 < 200 then lcd.drawText(2, 56, #tr > 18 and tr or \"tribute: \" .. tr, SMLSIZE)\n  else lcd.drawText(2, 56, \"L stick up or SA/SD\", SMLSIZE) end\n  return lv, prac, ip\nend, ip\nend\n"};
